import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, AmbientLight, DirectionalLight, Vector3, RepeatWrapping } = ctx.THREE;
  const group = new Group();

  const timelines = [];

  // 1. BACKDROP STAGE: Gradient panel to resolve voids (W-PCP §2.1)
  const bgGeom = new PlaneGeometry(8, 6);
  const bgMat = new MeshBasicNodeMaterial();
  // Vertical engineering gradient matching ink and surface
  bgMat.colorNode = mix(
    vec3(0.043, 0.043, 0.063), // #0b0b10 (surface)
    vec3(0.086, 0.086, 0.114), // #16161d (ink)
    uv().y
  );
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -1.0;
  group.add(bgMesh);

  // 2. HERO CARD PLANE
  const cardWidth = 3.4;
  const cardHeight = 1.2;
  const cardGeom = new PlaneGeometry(cardWidth, cardHeight);

  // Machined-metal character as per "Effects: static composition" 
  const cardMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.55,
    roughnessMap: null,
    transparent: true,
    opacity: 0.98
  });

  // Load image texture safely
  const imageUrl = config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.wrapS = RepeatWrapping;
    tex.wrapT = RepeatWrapping;
    tex.repeat.set(1.5, 1.5);
    cardMat.map = tex;
    cardMat.needsUpdate = true;
  });

  const cardMesh = new Mesh(cardGeom, cardMat);
  group.add(cardMesh);

  // 3. ENVELOPE ACCENT BORDER (Signal color bottom anchor)
  const accentGeom = new PlaneGeometry(cardWidth, 0.02);
  const accentMat = new MeshBasicNodeMaterial({ color: '#ff2a38' }); // signal red
  const accentMesh = new Mesh(accentGeom, accentMat);
  accentMesh.position.set(0, -cardHeight / 2 + 0.01, 0.01);
  group.add(accentMesh);

  // 4. MICRO METALLIC FRAME
  const frameGeom = new PlaneGeometry(cardWidth + 0.04, cardHeight + 0.04);
  const frameMat = new MeshBasicNodeMaterial({ color: '#16161d' }); // dark frame
  const frameMesh = new Mesh(frameGeom, frameMat);
  frameMesh.position.z = -0.01;
  group.add(frameMesh);

  // 5. LOCALIZED LIGHTS (W-PCP §2.4)
  const ambientLight = new AmbientLight(0xffffff, 0.8);
  group.add(ambientLight);

  const keyLight = new DirectionalLight('#e8ecf2', 1.2);
  keyLight.position.set(3, 4, 3);
  group.add(keyLight);

  const rimLight = new DirectionalLight('#ff2a38', 0.9); // Rim carrying accent hue
  rimLight.position.set(-3, -2, 2);
  group.add(rimLight);

  // 6. TYPOGRAPHY - Lora (serif, display role)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textHeadline = textItems.find(i => i.role === 'headline') || { text: 'Collection 2' };

  const textLabel = ctx.fontAtlas.createText(textHeadline.text || 'Collection 2', {
    fontSize: 0.22, // scale 39px down cleanly
    color: '#e8ecf2', // secondary paper contrast
    align: 'center'
  });
  textLabel.position.set(0, -0.05, 0.045);
  group.add(textLabel);

  // Apply visual-level cinematic entities via parameters
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives[primitive.name]) {
        const primHook = ctx.primitives[primitive.name](group, primitive.params);
        if (primHook && primHook.cleanup) {
          timelines.push(primHook);
        }
      }
    });
  }

  // Cleanup references and listeners
  group.userData.cleanup = () => {
    timelines.forEach(item => {
      if (item.timeline) item.timeline.kill();
      if (item.cleanup) item.cleanup();
    });
    bgGeom.dispose();
    bgMat.dispose();
    cardGeom.dispose();
    cardMat.dispose();
    accentGeom.dispose();
    accentMat.dispose();
    frameGeom.dispose();
    frameMat.dispose();
  };

  return group;
}
